WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_73790404ddbb8229>
    <urn:graphragprov:unit:u_ecbb0e68cbaebcca>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
